package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerSouthFifteenExpiryBudgetTest {
 private Crab south15,west;
 private Crab add(Room r,int key,int born,int wave,Lane lane,boolean big,Style style,int x,int y){Crab c=new Crab(key,key,born,wave,lane,'S',big,style,RangerStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private Room room(){Room r=new Room();r.wave=18;r.spawns[18]=144;r.ready=144;r.player=RangerStrategy.tile(3293,4248);south15=add(r,72,108,15,Lane.SOUTH,true,Style.MAGIC,3292,4244);for(int i=0;i<3;i++)add(r,80+i,132,17,Lane.values()[i],true,Style.MELEE,3299,4251);west=add(r,87,144,18,Lane.WEST,true,Style.RANGE,3281,4248);add(r,88,144,18,Lane.SOUTH,true,Style.RANGE,3293,4233);add(r,89,144,18,Lane.EAST,true,Style.RANGE,3309,4248);return r;}
 @Test public void knownSouthExpiryPreventsTheEarlyUntouchedWestBowPop(){Room r=room();Decision d=new RangerStrategy().decide(r,144);assertNull(d.reason,d.target);assertNotSame(west,d.approach);}
 @Test public void normalSouthLifetimeKeepsTheEarlyWestOpening(){Room r=room();r.crabs.remove(south15);south15=add(r,72,112,15,Lane.SOUTH,true,Style.MAGIC,3292,4244);assertSame(west,new RangerStrategy().decide(r,144).target);}
 @Test public void realWestSurvivorAndPendingDamageReleaseTheHold(){Room r=room();west.hp=7;assertSame(west,new RangerStrategy().decide(r,144).target);r=room();west.pendingDamage=3;assertSame(west,new RangerStrategy().decide(r,144).target);}
 @Test public void actualPriorZeroRollIsStillOpenedAndMustContinue(){Room r=room();RangerStrategy s=new RangerStrategy();s.attacked(new Decision(west,Weapon.BOW,r.player,false,null,"actualzero"),143);assertSame(west,s.decide(r,144).target);}
 @Test public void releaseAtActualNineteenPlusSixKeepsAllParentWorkAvailable(){Room r=room();r.wave=19;r.spawns[19]=152;r.ready=158;r.player=RangerStrategy.tile(3291,4246);west.point=RangerStrategy.tile(3290,4248);r.crabs.get(5).point=RangerStrategy.tile(3293,4243);r.crabs.get(6).point=RangerStrategy.tile(3295,4253);Decision d=new RangerStrategy().decide(r,158);assertSame(d.reason,west,d.target);assertEquals(Weapon.PIPE,d.weapon);}
 @Test public void aRealEighteenCapRetryCanUseWestImmediately(){Room r=room();r.ready=152;west.point=RangerStrategy.tile(3289,4248);for(int i=0;i<5;i++)add(r,100+i,140,18,Lane.SPLIT,false,Style.MELEE,3300,4253);Decision d=new RangerStrategy().decide(r,152);assertSame(d.reason,west,d.target);}
 @Test public void lateNineteenBirthReleasesRatherThanSpendTheRemainingParentBudget(){Room r=room();r.wave=19;r.spawns[19]=156;r.ready=156;west.point=RangerStrategy.tile(3290,4248);assertSame(west,new RangerStrategy().decide(r,156).target);}
 @Test public void unknownOrLethalSouthCoverageDoesNotAssertNaturalExpiryRisk(){for(int g=0;g<2;g++){Room r=room();south15.pendingDamage=g==0?-1:16;assertSame(west,new RangerStrategy().decide(r,144).target);}}
 @Test public void nullOrUnknownOtherParentsDoNotCreateAnUnmodeledBudget(){for(int g=0;g<2;g++){Room r=room();Crab other=r.crabs.get(5);if(g==0)other.nulled=true;else other.pendingDamage=-1;assertSame(west,new RangerStrategy().decide(r,144).target);}}
 @Test public void originalNineteenEyePacketKeepsItsActualRequestThree(){Room r=room();r.wave=19;r.spawns[19]=152;r.ready=155;r.player=RangerStrategy.tile(3291,4246);west.point=RangerStrategy.tile(3290,4248);Crab packet=add(r,90,152,19,Lane.WEST,true,Style.MAGIC,3284,4248);Decision d=new RangerStrategy().decide(r,155);assertSame(d.reason,packet,d.target);assertEquals(Weapon.EYE,d.weapon);}
}